// LendingPool 借贷池
// 存储某个币种的借贷池状态
type LendingPool struct {
	// denom 币种
	// 例如："USDT", "INJ" 等，每个币种对应一个独立的借贷池
	Denom string `protobuf:"bytes,1,opt,name=denom,proto3" json:"denom,omitempty"`
	// total_supply 总供应量
	// 所有存款人存入的总金额（包括已借出的部分）
	// 当借款人支付利息时，此值会增加（复利机制）
	TotalSupply cosmossdk_io_math.LegacyDec `protobuf:"bytes,2,opt,name=total_supply,json=totalSupply,proto3,customtype=cosmossdk.io/math.LegacyDec" json:"total_supply"`
	// total_borrowed 总借贷量
	// 当前所有借款人借出的总金额（不包括利息）
	TotalBorrowed cosmossdk_io_math.LegacyDec `protobuf:"bytes,3,opt,name=total_borrowed,json=totalBorrowed,proto3,customtype=cosmossdk.io/math.LegacyDec" json:"total_borrowed"`
	// total_shares 总份额
	// 所有存款人持有的总份额数，用于按比例分配利息
	// 份额机制：存入时按比例获得份额，提取时按份额计算可取金额
	// 当利息分配时，TotalSupply 增加但 TotalShares 不变，使每个份额价值增加
	// total_shares 示例说明：
	// 1. 假设池子刚启动，为空。第一个用户A存入100 USDT。
	//    - 此时 TotalSupply = 100，TotalShares =
	//    100（我们默认1:1，用户A获得100份额）。
	//    - 用户A的份额: 100
	//
	// 2. 随着时间推移，借款人支付了2 USDT利息，池中金额变为102 USDT，TotalSupply
	// = 102，但 TotalShares 仍然=100。
	//    - 用户A仍持有100份额，此时每份额价值 = 102 / 100 = 1.02 USDT。
	//
	// 3. 这时，用户B看到池中有利息后，存入98 USDT。
	//    - 用户B获得的份额 = 存入金额 / 当前每份额价值 = 98 / 1.02 ≈ 96.08 份额。
	//    - 此时 TotalSupply = 200，TotalShares = 100 + 96.08 = 196.08
	//    - 用户A: 100份额，用户B: 96.08份额
	//
	// 4. 再过一段时间，借款人又支付了1 USDT利息（此时池子有201 USDT）。
	//    - TotalSupply = 201, TotalShares = 196.08（不变）
	//    - 每份额价值 = 201 / 196.08 ≈ 1.025
	//
	// 5. 当A想赎回全部资产时，可取金额 = A份额 × 现每份额价值 = 100 × 1.025 ≈
	// 102.5 USDT
	//    B如果全部赎回，B可取 = 96.08 × 1.025 ≈ 98.5 USDT
	//
	// 总结：用户存款会按当前池子的每份额价值分配份额，利息进来只增加总金额（TotalSupply），不增加份额（TotalShares），
	// 这样保证存款越早、持有时间越久的人受益越多。
	TotalShares cosmossdk_io_math.LegacyDec `protobuf:"bytes,4,opt,name=total_shares,json=totalShares,proto3,customtype=cosmossdk.io/math.LegacyDec" json:"total_shares"`
	// utilization_rate 利用率
	// 计算公式：UtilizationRate = TotalBorrowed / TotalSupply
	// 表示借贷池的资金使用率，用于动态调整利率
	// 利用率越高，借贷利率越高，以鼓励存款和抑制借贷
	UtilizationRate cosmossdk_io_math.LegacyDec `protobuf:"bytes,5,opt,name=utilization_rate,json=utilizationRate,proto3,customtype=cosmossdk.io/math.LegacyDec" json:"utilization_rate"`
	// borrow_rate 借贷利率（年化利率）
	// 借款人需要支付的年化利率，根据利用率动态调整
	// 利率模型：分段线性模型，利用率越高利率越高
	BorrowRate cosmossdk_io_math.LegacyDec `protobuf:"bytes,6,opt,name=borrow_rate,json=borrowRate,proto3,customtype=cosmossdk.io/math.LegacyDec" json:"borrow_rate"`
	// supply_rate 存款利率（年化利率）
	// 存款人可以获得的年化利率，通常低于借贷利率
	// 计算公式：SupplyRate = BorrowRate × UtilizationRate × (1 - ReserveFactor)
	SupplyRate cosmossdk_io_math.LegacyDec `protobuf:"bytes,7,opt,name=supply_rate,json=supplyRate,proto3,customtype=cosmossdk.io/math.LegacyDec" json:"supply_rate"`
	// reserve_amount 准备金金额
	// 平台从利息收入中提取的准备金，用于风险缓冲
	// 计算公式：ReserveAmount += CollectedInterest × PlatformShareRatio
	ReserveAmount cosmossdk_io_math.LegacyDec `protobuf:"bytes,8,opt,name=reserve_amount,json=reserveAmount,proto3,customtype=cosmossdk.io/math.LegacyDec" json:"reserve_amount"`
}

