// RiskMetrics 风险指标
// 存储账户的风险计算指标，用于风险监控和清算判断
type RiskMetrics struct {
	// subaccount_id 子账户ID（字符串格式）
	// 标识风险指标所属的账户
	SubaccountId string `protobuf:"bytes,1,opt,name=subaccount_id,json=subaccountId,proto3" json:"subaccount_id,omitempty"`
	// total_asset_value 总资产价值（USDT计价）
	// 账户所有资产的总价值，包括所有币种的余额和持仓价值
	// 计算公式：TotalAssetValue = Σ(AssetAmount × AssetPriceInUSDT)
	TotalAssetValue cosmossdk_io_math.LegacyDec `protobuf:"bytes,2,opt,name=total_asset_value,json=totalAssetValue,proto3,customtype=cosmossdk.io/math.LegacyDec" json:"total_asset_value"`
	// total_borrow_value 总借贷价值（USDT计价）
	// 账户所有借贷的总价值，包括本金和累计利息
	// 计算公式：TotalBorrowValue = Σ(BorrowAmount × BorrowPriceInUSDT) +
	// AccruedInterest
	TotalBorrowValue cosmossdk_io_math.LegacyDec `protobuf:"bytes,3,opt,name=total_borrow_value,json=totalBorrowValue,proto3,customtype=cosmossdk.io/math.LegacyDec" json:"total_borrow_value"`
	// account_equity 账户净值（权益，USDT计价）
	// 账户的实际价值，等于总资产减去总借贷
	// 计算公式：AccountEquity = TotalAssetValue - TotalBorrowValue
	AccountEquity cosmossdk_io_math.LegacyDec `protobuf:"bytes,4,opt,name=account_equity,json=accountEquity,proto3,customtype=cosmossdk.io/math.LegacyDec" json:"account_equity"`
	// maintenance_margin 维持保证金（USDT计价）
	// 账户需要维持的最小保证金，低于此值将触发清算
	// 计算公式：MaintenanceMargin = TotalAssetValue × MaintenanceMarginRate
	MaintenanceMargin cosmossdk_io_math.LegacyDec `protobuf:"bytes,5,opt,name=maintenance_margin,json=maintenanceMargin,proto3,customtype=cosmossdk.io/math.LegacyDec" json:"maintenance_margin"`
	// margin_ratio 保证金率（百分比）
	// 账户净值与维持保证金的比率，用于判断风险等级
	// 计算公式：MarginRatio = AccountEquity / MaintenanceMargin × 100%
	// 例如："150" 表示账户净值是维持保证金的 1.5 倍
	MarginRatio cosmossdk_io_math.LegacyDec `protobuf:"bytes,6,opt,name=margin_ratio,json=marginRatio,proto3,customtype=cosmossdk.io/math.LegacyDec" json:"margin_ratio"`
	// available_balance 可用余额（USDT计价）
	// 账户可以用于提现或下单的余额
	// 计算公式：AvailableBalance = AccountEquity - MaintenanceMargin
	// 如果为负，表示账户已触发清算条件
	AvailableBalance cosmossdk_io_math.LegacyDec `protobuf:"bytes,7,opt,name=available_balance,json=availableBalance,proto3,customtype=cosmossdk.io/math.LegacyDec" json:"available_balance"`
	// risk_level 风险等级
	// 0: Safe（安全）- 保证金率 > 200%
	// 1: Normal（正常）- 保证金率 150-200%
	// 2: Warning（警告）- 保证金率 120-150%
	// 3: Danger（危险）- 保证金率 100-120%
	// 4: Liquidation（清算）- 保证金率 < 100%
	RiskLevel int32 `protobuf:"varint,8,opt,name=risk_level,json=riskLevel,proto3" json:"risk_level,omitempty"`
}

